    exitAt('exit', 7, 2, 'field', ['To the battlefield', 'אל שדה הקרב'], () => fl('signed') || ['quartermaster', ['Oi! Nobody leaves this camp without signing for something.', 'היי! אף אחד לא יוצא מהמחנה בלי לחתום על משהו.']]);
