    g.add(mesh(new THREE.CircleGeometry(0.16, 10).rotateX(-Math.PI / 2), mat(C.oil, { roughness: 0.12, emissive: '#5a3c00', emissiveIntensity: 0.4, flatShading: false }), 0, 0.2, 0, false));
